// Arabic texts of catalog.mjs: [English text, Arabic text], in catalog order. The English side must match the T() text
// exactly (the build names any text without a translation and any entry whose English text changed or went away).
// Terms follow the app (src/Filee.App/Assets/i18n/ar.json): الإعداد المسبق (preset), المحركات (engines), شريط الأدوات
// الدائري (donut toolbar), مراقبة المجلدات (watch folders), منطقة الإفلات (drop zone), preset names as in the app.
// Western digits as in the app; U+200E / U+200F marks keep Latin runs (.ext, /switches, brackets) on the right side.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `الفيديو والصوت، واستخراج الترجمة، والحفظ بصيغة HEIC`],
  [`older office formats such as DOC, PPT and ODT`,
    `صيغ المستندات المكتبية القديمة مثل DOC وPPT وODT`],
  [`rare e-book formats and MOBI/AZW3 output`,
    `صيغ الكتب الإلكترونية النادرة والحفظ بصيغة MOBI/AZW3`],
  [`EPS and PostScript`, `EPS وPostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX وOrg وAsciiDoc وغيرها من لغات الترميز، وWord → Markdown، وMarkdown → شرائح`],

  // Options
  [`quality`, `الجودة`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `جودة قابلة للضبط لصيغ JPG وWEBP وAVIF: تُحفظ JPG افتراضيًا بجودة 90%، ويُنتج الإعداد المسبق «JPG 70%» ملفات أصغر.`],
  [`resize`, `تغيير الحجم`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `تغيير الحجم أثناء التحويل، بنسبة مئوية (مثل نصف الحجم) أو بتحديد حد أقصى للضلع الأطول.`],
  [`DPI`, `دقة DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `تعيين قيمة DPI المكتوبة في الصورة، مثل 300 للطباعة.`],
  [`grayscale`, `تدرّج رمادي`],
  [`A grayscale preset makes black-and-white copies.`,
    `يُنشئ الإعداد المسبق «تدرّج رمادي» نسخًا بالأبيض والأسود.`],
  [`metadata`, `البيانات الوصفية`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `يُحتفظ بالبيانات الوصفية (EXIF وXMP وملف تعريف الألوان) افتراضيًا، ويمكن إزالتها حفاظًا على الخصوصية.`],
  [`ICO sizes`, `أحجام ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `تحتوي ملفات ICO افتراضيًا على الأحجام 256 و128 و64 و48 و32 و16 بكسل، ويمكن تغييرها في الإعداد المسبق.`],
  [`TIFF compression`, `ضغط TIFF`],
  [`TIFF compression can be chosen (LZW by default).`,
    `يمكن اختيار طريقة ضغط TIFF \u200F(LZW افتراضيًا).`],
  [`white background`, `خلفية بيضاء`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `لا تدعم JPG الشفافية، لذا تُملأ المناطق الشفافة باللون الأبيض.`],
  [`merge into one PDF`, `الدمج في PDF واحد`],
  [`The merge preset combines all dropped files into one PDF.`,
    `يجمع الإعداد المسبق «دمج PDF» كل الملفات المُفلَتة في ملف PDF واحد.`],
  [`split pages`, `تقسيم الصفحات`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `يحفظ الإعداد المسبق «تقسيم PDF» كل صفحة في ملف PDF مستقل داخل مجلد فرعي.`],
  [`rotate & flip`, `التدوير والانعكاس`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `تُدوِّر الإعدادات المسبقة للتدوير والانعكاس الصور لليسار أو لليمين أو 180° وتعكسها، بعد مراعاة الاتجاه المسجّل في الصورة نفسها.`],
  [`Trace to SVG`, `تتبّع إلى SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `يحوّل إعدادان مسبقان الصورة إلى أشكال متجهية: «تتبّع إلى SVG» بما يصل إلى 64 لونًا، و«رسم خطي إلى SVG» باللون الأسود للشعارات والتواقيع والمستندات الممسوحة ضوئيًا. لا حاجة إلى أي برنامج آخر.`],
  [`remove background`, `إزالة الخلفية`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `يجعل الإعداد المسبق «إزالة الخلفية» الخلفيةَ البسيطة شفافة: الورق خلف توقيع أو ختم، أو خلفية شعار.`],
  [`page ranges`, `نطاقات الصفحات`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `تقصر نطاقات الصفحات مثل 1-3,5 التحويلَ على الصفحات التي تحتاجها.`],
  [`render DPI`, `دقة التصيير`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `تُصيَّر الصفحات افتراضيًا بدقة 150 DPI؛ اختر 300 DPI لجودة الطباعة.`],
  [`one long image`, `صورة طويلة واحدة`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `يجمع الإعداد المسبق «صورة طويلة» كل الصفحات بعضها تحت بعض في صورة طويلة واحدة، مثلًا لنشر مستند كامل دفعة واحدة.`],
  [`compress PDF`, `ضغط PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `يقلّل الإعداد المسبق «ضغط PDF» حجم ملف PDF مع بقائه PDF: تُصغَّر الصور إلى 72 أو 150 أو 300 dpi ويُعاد حفظ الصور الفوتوغرافية بصيغة JPEG، بينما تبقى النصوص والخطوط والروابط والإشارات المرجعية والنماذج كما هي. وإذا تعذّر تصغير ملف PDF يُترك كما هو. وعند تثبيت Ghostscript، يستطيع Filee تجربته أيضًا والاحتفاظ بالنتيجة الأصغر.`],
  [`a picture per slide`, `صورة لكل شريحة`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `يضع «PPTX \u200F(شرائح)» صورة لكل صفحة على شريحة مستقلة بحجم الصفحة، مع نص الصفحة في ملاحظات المتحدث. تبدو الشرائح مطابقة تمامًا لملف PDF لكنها غير قابلة للتحرير؛ حوّل إلى DOCX للحصول على نص قابل للتحرير.`],
  [`vector PDF`, `PDF متجهي`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `يبقى ملف PDF متجهيًا، فيظل واضحًا بأي درجة تكبير وعند الطباعة.`],
  [`editable`, `قابل للتحرير`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `تحتوي النتيجة على نص وفقرات حقيقية يمكنك تحريرها، لا على صور للصفحات.`],
  [`attachments as ZIP`, `المرفقات في ZIP`],
  [`Attachments can be saved separately as one ZIP.`,
    `يمكن حفظ المرفقات بشكل منفصل في ملف ZIP واحد.`],
  [`one CSV per sheet`, `ملف CSV لكل ورقة`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `تُنتج المصنفات ذات الأوراق المتعددة ملف CSV لكل ورقة.`],
  [`layout kept`, `الحفاظ على التخطيط`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `يحافظ على حجم الصفحة وهوامشها، والرؤوس والتذييلات مع أرقام الصفحات، والجداول ومربعات النص والأشكال والصور.`],
  [`no Office needed`, `دون الحاجة إلى Office`],
  [`No Microsoft Office or LibreOffice needed.`,
    `لا حاجة إلى Microsoft Office أو LibreOffice.`],
  [`no Hancom Office needed`, `دون الحاجة إلى Hancom Office`],
  [`No Hancom Office and no approval dialog.`,
    `دون Hancom Office ودون نافذة طلب الإذن.`],
  [`no AutoCAD needed`, `دون الحاجة إلى AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`, `لا حاجة إلى AutoCAD أو عارض DWG.`],
  [`no re-encoding`, `دون إعادة ترميز`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `عندما تستطيع الصيغة الجديدة الاحتفاظ بالفيديو والصوت كما هما (MOV من iPhone إلى MP4)، تتغير الحاوية فقط: دون فقدان في الجودة، مع الاحتفاظ بـ HDR، وخلال ثوانٍ.`],
  [`720p option`, `خيار 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `يصغّر الإعداد المسبق «MP4 720p» مقاطع الفيديو الكبيرة لمشاركتها.`],
  [`extract audio`, `استخراج الصوت`],
  [`Only the sound is saved, without the video track.`,
    `يُحفظ الصوت فقط، دون مسار الفيديو.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `يُنتج الإعداد المسبق «MP3 128k» ملفات أصغر، وهو مثالي للكلام.`],
  [`extract`, `الاستخراج`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `أما الإعداد المسبق «استخراج» فيفك ضغط الأرشيف إلى مجلد بدلًا من ذلك.`],
  [`pack into one ZIP`, `الجمع في ZIP واحد`],
  [`Any selection of files can be packed into one ZIP.`,
    `يمكن جمع أي ملفات تحددها في ملف ZIP واحد.`],
  [`DRM-free books`, `كتب خالية من DRM`],
  [`Works with DRM-free books only.`, `يعمل مع الكتب الخالية من DRM فقط.`],
  [`ALAC in M4A`, `ALAC في M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`,
    `يمكن أن يحتوي M4A على صوت ALAC دون فقدان إلى جانب AAC.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `يمكن للإعدادات المسبقة للفيديو الترميز بـ HEVC \u200F(H.265) أو AV1 للحصول على ملفات أصغر، مع الاحتفاظ بفيديو 10 بت وHDR.`],
  [`hardware encoding`, `الترميز بالعتاد`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `فعّل «استخدام تسريع العتاد» في إعداد مسبق للفيديو لترميز H.264 وHEVC باستخدام معالج الرسوميات (NVENC أو Quick Sync أو AMF أو VideoToolbox أو VA-API): أسرع بكثير وأقل استهلاكًا للطاقة، مع حجم أكبر قليلًا عند الجودة نفسها. الخيار معطّل افتراضيًا، وعند عدم توفر معالج مناسب يُرمَّز الفيديو كالمعتاد.`],
  [`every frame`, `كل الإطارات`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `عادةً ما ينتج عن الفيديو إطار ثابت واحد. أما الإعدادات المسبقة «استخراج الإطارات»، أو خيار «حفظ كل إطار من الفيديو» في إعداد مسبق لـ PNG أو JPG، فتحفظ كل إطار (أو كل إطار رقم N) كصور في مجلد بجانب الفيديو.`],
  [`extract subtitles`, `استخراج الترجمة`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `يحفظ الإعداد المسبق «استخراج الترجمة» في الشريط الدائري للفيديو أولَ مسار ترجمة نصية في الفيديو بصيغة SRT.`],
  [`saved as UTF-8`, `الحفظ بترميز UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `تُحفظ النتائج بترميز UTF-8. وتُكتشف الملفات الكورية المحفوظة بترميز CP949 \u200F(EUC-KR) وتُقرأ بصورة صحيحة.`],
  [`tables to CSV / Excel`, `الجداول إلى CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `البيانات الجدولية (قائمة من السجلات) تُحوَّل أيضًا من CSV وExcel وإليهما.`],
  [`picture preview`, `معاينة بصورة`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `يُنتج PNG أو JPG صورة مظلّلة للنموذج، من الأمام يمينًا ومن الأعلى.`],
  [`colours and textures`, `الألوان والخامات`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `يُحتفظ بالألوان والخامات والمواد حيثما تدعمها الصيغة الهدف. أما STL فيحتفظ بالشكل فقط.`],
  [`HDR tone-mapped`, `HDR مع ضبط الدرجات`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `تُضبط درجات لقطات شاشة HDR التي يحفظها Windows بصيغة JPEG XR إلى سطوع عادي بدلًا من قص المناطق الساطعة.`],
  [`Live Photo video`, `فيديو Live Photo`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `يحفظ الإعداد المسبق «استخراج فيديو Live Photo» فيديو صورة Live Photo من iPhone \u200F(ملف LIVP من iCloud، أو صورة مع ملف MOV الخاص بها) أو صورة Motion Photo من Android بصيغة MP4 أو MOV. وفي الاتجاه المعاكس، يحوّل الإعدادان المسبقان «Live Photo \u200F(iPhone)» و«Motion Photo \u200F(Android)» مقطعًا قصيرًا من فيديو إلى صورة متحركة؛ وهذه الميزة لا تزال تجريبية.`],
  [`WGS 84 longitude / latitude`, `خطوط الطول والعرض WGS 84`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `تكون النتائج دائمًا بخطوط الطول والعرض (WGS 84). تُحوَّل ملفات Shapefile ذات الإسقاط UTM أو Web Mercator أو Lambert أو Albers لتظهر في موضعها الصحيح؛ وتحويل الملف إلى صيغته نفسها يعيد إسقاطه.`],
  [`save as ZIP`, `الحفظ بصيغة ZIP`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `يتكون Shapefile من خمسة ملفات (\u200E.shp و\u200E.shx و\u200E.dbf و\u200E.prj و\u200E.cpg). ومع خيار «حفظ النتيجة بصيغة ZIP» في إعداد مسبق، أو لكل النتائج الجغرافية من الإعدادات، تنتقل معًا في ملف ZIP واحد.`],

  // Camera RAW
  [`Canon CR2 RAW photo`, `صورة RAW بصيغة CR2 من Canon`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 هي صيغة صور RAW التي استخدمتها كاميرات Canon DSLR لسنوات طويلة (تحفظ طرازات Canon الأحدث بصيغة CR3). وتخزّن بيانات المستشعر غير المعالجة، ما يترك مساحة واسعة للتعديل.`],
  [`Nikon NEF RAW photo`, `صورة RAW بصيغة NEF من Nikon`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF هي صيغة صور RAW من Nikon، وتستخدمها كاميرات Nikon DSLR وكاميرات Z عديمة المرآة. وكغيرها من ملفات RAW، تحتوي على بيانات المستشعر غير المعالجة، وحجمها أكبر من JPG بعدة أضعاف.`],

  // Images
  [`Images`, `الصور`],
  [`images`, `الصور`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `الصور الفوتوغرافية والرسومات، بما فيها HEIC وLive Photos من iPhone، وPSD من Photoshop، وصور RAW من كاميرات جميع العلامات التجارية الكبرى، وAPNG المتحركة، وDICOM، ولقطات شاشة HDR في Windows \u200F(JPEG XR). غيّر الحجم ودوّر الصور واضبط الجودة وDPI أو أزل البيانات الوصفية أثناء التحويل، أو تتبّع صورة إلى SVG.`],
  [`JPEG image`, `صورة JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG هي صيغة الصور الأكثر استخدامًا. يُبقي ضغطها مع الفقدان الملفات صغيرة، لكن كل حفظ بجودة أقل يُضيّع بعض التفاصيل، ولا تدعم الشفافية.`],
  [`PNG image`, `صورة PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG صيغة صور دون فقدان تدعم الشفافية، وهي مثالية للقطات الشاشة والشعارات والرسومات ذات الحواف الحادة. أما الصور الفوتوغرافية المحفوظة بصيغة PNG فتكون عادةً أكبر بكثير من JPG.`],
  [`WebP image`, `صورة WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP صيغة صور من Google مخصصة للويب. تدعم الضغط مع الفقدان ودونه والشفافية، وعادةً ما تكون أصغر من JPG أو PNG، لكن بعض برامج التحرير ونماذج الرفع لا تقبلها بعد.`],
  [`AVIF image`, `صورة AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF صيغة صور حديثة تعتمد على ترميز الفيديو AV1. ضغطها أفضل من JPG وWebP، لكن دعمها في البرامج والأجهزة القديمة لا يزال محدودًا.`],
  [`HEIC / HEIF image`, `صورة HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC \u200F(HEIF) هي صيغة الصور الافتراضية في أجهزة iPhone وiPad. وغالبًا ما يكون حجم الصورة نحو نصف حجم JPG، لكن كثيرًا من تطبيقات Windows والمواقع والأجهزة القديمة لا تستطيع فتحها.`],
  [`GIF image / animation`, `صورة GIF أو رسم متحرك`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF صيغة صور قديمة محدودة بـ 256 لونًا وتدعم الرسوم المتحركة البسيطة. ولا تزال الطريقة المعتمدة في كل مكان لمشاركة المقاطع القصيرة الصامتة المتكررة في المحادثات والمستندات وتقارير الأخطاء.`],
  [`Windows icon`, `أيقونة Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO هي صيغة أيقونات Windows. يحتوي ملف ICO الواحد على الصورة نفسها بعدة أحجام (مثل 16 و32 و48 و256 بكسل)، فتبدو واضحة في كل مكان، من شريط المهام إلى أيقونات المواقع (favicon).`],
  [`Photoshop document`, `مستند Photoshop`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD هي الصيغة الأصلية لبرنامج Adobe Photoshop. تحتفظ بالطبقات والأقنعة وإعدادات الضبط، لذا فهي ممتازة للتحرير، لكن معظم برامج العرض والمواقع لا تستطيع فتحها.`],
  [`macOS icon`, `أيقونة macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS هي صيغة الأيقونات في macOS. وكما في ICO، تجمع عدة أحجام لصورة واحدة تصل إلى 1024×1024 لشاشات Retina، وتُستخدم لأيقونات التطبيقات على Mac.`],
  [`Camera RAW`, `صور RAW من الكاميرات`],
  [`Windows only`, `Windows فقط`],
  [`the photo of the Live Photo`, `الصورة من Live Photo`],
  [`the video of the Live Photo`, `الفيديو من Live Photo`],

  // Vector graphics
  [`Vector graphics`, `الرسومات المتجهية`],
  [`vector graphics`, `الرسومات المتجهية`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG وملفات Windows Metafile وIllustrator وEPS/PostScript ورسومات CorelDRAW وVisio وLibreOffice Draw. ويمكن أيضًا تحويل SVG إلى DXF أو DWG لبرامج CAD.`],
  [`SVG vector graphic`, `رسم متجهي SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG صيغة رسومات متجهية قائمة على XML. تبقى الأشكال والنصوص واضحة بأي حجم، ما يجعلها مثالية للشعارات والأيقونات على الويب، لكن كثيرًا من التطبيقات ونماذج الرفع لا تقبل إلا الصور النقطية.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS صيغة متجهية من عالم الطباعة والتصميم، تُستخدم غالبًا للشعارات والرسوم التوضيحية المرسلة إلى المطابع. ولا تستطيع معظم التطبيقات الحديثة عرضها دون مفسّر PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `ملفات AI المحفوظة بمحتوى PDF \u200F(الإعداد الافتراضي في Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `حوّل ملفات PDF إلى صور، أو مستندات Word أو HWPX قابلة للتحرير، أو شرائح PowerPoint، أو نص، أو أرشيف قصص مصورة، وادمجها أو قسّمها أو اضغطها أو اختر منها صفحات.`],
  [`PDF document`, `مستند PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF هو المعيار المعتمد لمشاركة المستندات التي يجب أن تبدو متطابقة في كل مكان. خطوطه وتخطيطه وصوره ثابتة، ويُفتح على أي جهاز. وهذا أيضًا ما يجعل تحرير ملفات PDF صعبًا.`],
  [`one page`, `صفحة واحدة`],

  // Documents
  [`Documents`, `المستندات`],
  [`documents`, `المستندات`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `مستندات Word دون Microsoft Office، والفواتير الإلكترونية الصينية OFD، وصيغ معالجة النصوص القديمة والنادرة عبر محرك LibreOffice الاختياري، ورسائل البريد الإلكتروني المحفوظة (EML وOutlook MSG).`],
  [`Word document`, `مستند Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX هي صيغة Microsoft Word منذ Word 2007 \u200F(Office Open XML). وهي الصيغة الأكثر شيوعًا للمستندات القابلة للتحرير مثل التقارير والرسائل والنماذج.`],
  [`Word 97–2003 document`, `مستند Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC هي الصيغة الثنائية لـ Word 97–2003. ولا تزال الأرشيفات القديمة والنماذج الرسمية والأنظمة القديمة تُنتجها، لكن DOCX تحل محلها تدريجيًا.`],
  [`E-mail message`, `رسالة بريد إلكتروني`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML رسالة بريد إلكتروني واحدة محفوظة كملف (بصيغة MIME)، مع الترويسات ونص الرسالة ومرفقاتها. وتستطيع معظم تطبيقات البريد، ومنها Outlook وThunderbird، فتحها.`],
  [`Outlook message`, `رسالة Outlook`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG هو الملف الذي يحفظه Microsoft Outlook عند سحب رسالة بريد منه. ولا يفتحه إلا Outlook، لذا تصعب قراءته على حاسوب دون Outlook أو على الهاتف.`],

  // HWP
  [`HWP (Hangul)`, `HWP \u200F(Hangul)`],
  [`Korean HWP/HWPX`, `HWP/HWPX الكورية`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `مستندات Hancom Hangul الكورية دون Hancom Office: HWP ↔ HWPX، وإلى PDF والصور وWord والنص وMarkdown وHTML، وHWPX من Word وExcel وPowerPoint وMarkdown وPDF.`],
  [`Hangul document (HWP)`, `مستند Hangul \u200F(HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP هي صيغة مستندات Hancom Office Hangul \u200F(한글)، معالج النصوص المعتمد في الدوائر الحكومية والمدارس وكثير من الشركات في كوريا. وخارج كوريا، قليلة هي البرامج التي تستطيع فتحها.`],
  [`Hangul document (HWPX)`, `مستند Hangul \u200F(HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX هي الصيغة المفتوحة القائمة على XML لبرنامج Hancom Hangul \u200F(OWPML، المعيار الوطني الكوري KS X 6101). وتنتقل المؤسسات العامة الكورية إليها من صيغة HWP الثنائية.`],

  // Spreadsheets
  [`Spreadsheets`, `جداول البيانات`],
  [`spreadsheets`, `جداول البيانات`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `جداول Excel وOpenDocument وCSV/TSV، إلى PDF مع ملاءمة الصفحات كما في Excel أو فيما بينها، دون Excel.`],
  [`Excel workbook`, `مصنف Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX هي صيغة مصنفات Microsoft Excel منذ Excel 2007. ويمكن للمصنف الواحد أن يضم عدة أوراق فيها صيغ حسابية وتنسيقات ومخططات وصور.`],
  [`Excel 97–2003 workbook`, `مصنف Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS هي صيغة المصنفات الثنائية في Excel 97–2003. ولا تزال كثير من الأنظمة القديمة وملفات التصدير المصرفية والمحاسبية تُنتجها.`],
  [`Comma-separated values`, `قيم مفصولة بفواصل`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV نص عادي يضم صفًا واحدًا من الجدول في كل سطر. تقرؤه كل برامج جداول البيانات وقواعد البيانات ولغات البرمجة، لكنه لا يدعم التنسيق ولا الصيغ الحسابية ولا الأوراق المتعددة.`],

  // Presentations
  [`Presentations`, `العروض التقديمية`],
  [`presentations`, `العروض التقديمية`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint إلى PDF والصور وHWPX دون PowerPoint؛ وملفات PPT القديمة وODP وKeynote عبر محرك LibreOffice الاختياري.`],
  [`PowerPoint presentation`, `عرض PowerPoint تقديمي`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX هي صيغة Microsoft PowerPoint منذ PowerPoint 2007. وتحتوي على شرائح فيها نصوص وصور وأشكال وجداول وملاحظات وحركات.`],
  [`PowerPoint 97–2003 presentation`, `عرض PowerPoint 97–2003 تقديمي`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT هي الصيغة الثنائية لـ PowerPoint 97–2003. وكثيرًا ما تبقى شرائح المحاضرات القديمة والعروض المؤرشفة بصيغة PPT.`],

  // Text & markup
  [`Text & markup`, `النصوص ولغات الترميز`],
  [`text and markup`, `النصوص ولغات الترميز`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `النص العادي وMarkdown وHTML وصفحات الويب المحفوظة (MHTML) إلى PDF وWord وHWPX وEPUB. أما LaTeX وreStructuredText وOrg وAsciiDoc وTypst وJupyter وغيرها من لغات الترميز فتستخدم محرك Pandoc الاختياري، الذي يحوّل أيضًا Markdown إلى شرائح PowerPoint.`],
  [`Plain text`, `نص عادي`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT نص عادي بلا أي تنسيق، وهو أبسط صيغ المستندات وأسهلها نقلًا بين الأنظمة. والشيء الوحيد الذي قد يختلف هو ترميز الأحرف (UTF-8 أو UTF-16 أو صفحة ترميز قديمة).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown لغة ترميز خفيفة بنص عادي: # للعناوين، و* للقوائم، و** للخط العريض. وهي شائعة في الملاحظات وملفات README والتوثيق، ويمكن قراءتها حتى دون عرضها منسّقة.`],
  [`Web page (HTML)`, `صفحة ويب (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML هي لغة صفحات الويب. يُفتح ملف \u200E.html المحفوظ في أي متصفح، لكن مظهره يعتمد على المتصفح وعلى الأنماط والصور المرتبطة به، وقد تكون مفقودة دون اتصال بالإنترنت.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `تُقرأ ملفات LOG والبرامج النصية (PY وPAC وBAT وCOMMAND) كنص ولا تُشغَّل أبدًا`],
  [`the saved page, with its pictures`, `الصفحة المحفوظة مع صورها`],

  // Data
  [`Data`, `البيانات`],
  [`data files`, `ملفات البيانات`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON وJSON Lines وYAML وTOML وXML فيما بينها، والجداول من CSV وExcel وإليهما. وجهات اتصال vCard من CSV وإليه، بما فيها جهات الاتصال من الهواتف القديمة. لا حاجة إلى تثبيت أي شيء.`],
  [`JSON data`, `بيانات JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON هي صيغة البيانات على الويب: كائنات وقوائم ونصوص وأرقام في نص عادي. وتستخدمها واجهات البرمجة (API) والتطبيقات وملفات الإعدادات في كل مكان.`],
  [`YAML data`, `بيانات YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `تحمل YAML نوع البيانات نفسه الذي تحمله JSON، لكنها تُكتب بالمسافات البادئة بدلًا من الأقواس. وملفات إعداد Docker وKubernetes ومسارات CI وكثير من التطبيقات مكتوبة بـ YAML.`],
  [`vCard contacts`, `جهات اتصال vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard \u200F(\u200E.vcf) هو الملف القياسي لجهات الاتصال. وتصدّر الهواتف وOutlook وGoogle Contacts وiCloud دفاتر العناوين بصيغة vCard، وغالبًا ما تكون جهات اتصال كثيرة في ملف واحد.`],

  // E-books & comics
  [`E-books & comics`, `الكتب الإلكترونية والقصص المصورة`],
  [`e-books and comics`, `الكتب الإلكترونية والقصص المصورة`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB وKindle \u200F(MOBI وAZW وAZW3) وFictionBook وأرشيفات القصص المصورة (CBZ وCBR وCB7…) إلى PDF وEPUB وWord وغيرها، وKEPUB لأجهزة Kobo. للكتب الخالية من DRM فقط.`],
  [`EPUB e-book`, `كتاب إلكتروني EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB هو المعيار المفتوح للكتب الإلكترونية. يتكيّف النص مع أي شاشة، وتدعمه معظم أجهزة القراءة وتطبيقاتها؛ ويقبل Kindle ملفات EPUB عبر Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `كتاب إلكتروني Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI هي صيغة Mobipocket القديمة للكتب الإلكترونية التي استخدمها Amazon Kindle لسنوات. ولا تزال شائعة في مجموعات الكتب الإلكترونية القديمة، لكن Amazon انتقلت إلى AZW3/KFX وEPUB.`],

  // Video
  [`Video`, `الفيديو`],
  [`video`, `الفيديو`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `جميع صيغ الفيديو الشائعة إلى MP4 \u200F(H.264 أو HEVC أو AV1) أو WebM أو MOV أو MKV أو AVI أو GIF أو APNG، مع خيار 720p، والترميز باستخدام معالج الرسوميات، واستخراج الصوت إلى MP3 أو M4A، وحفظ كل إطار كصورة. يستخدم محرك FFmpeg الاختياري.`],
  [`MPEG-4 video`, `فيديو MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 \u200F(MPEG-4 Part 14) هي صيغة الفيديو الأكثر توافقًا. تعمل على الهواتف والتلفزيونات والمتصفحات وكل مواقع الفيديو، وعادةً ما تضم فيديو H.264 أو H.265 وصوت AAC.`],
  [`QuickTime movie`, `فيلم QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV هي صيغة فيديو QuickTime من Apple، وتستخدمها أجهزة iPhone وMac. وعادةً ما تحتوي على فيديو H.264 أو HEVC، لكن بعض برامج التحرير والتلفزيونات والمواقع تتعامل مع MP4 بشكل أفضل.`],
  [`Matroska video`, `فيديو Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV \u200F(Matroska) حاوية مفتوحة ومرنة يمكنها أن تضم مسارات متعددة للفيديو والصوت والترجمة. وهي شائعة للأفلام والتسجيلات، لكن الهواتف والتلفزيونات وبرامج التحرير لا تشغّلها دائمًا.`],
  [`WebM video`, `فيديو WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM صيغة فيديو مفتوحة مصممة للمتصفحات (فيديو VP8/VP9 أو AV1 مع صوت Vorbis أو Opus). وكثيرًا ما تكون تسجيلات الشاشة والملفات المنزّلة بصيغة WebM، لكن كثيرًا من برامج التحرير والأجهزة تتوقع MP4.`],
  [`AVI video`, `فيديو AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI حاوية فيديو من Microsoft تعود إلى تسعينيات القرن الماضي. ولا تزال كاميرات الفيديو والكاميرات القديمة والأرشيفات تحتوي على ملفات AVI، وهي غالبًا كبيرة الحجم وضعيفة الدعم على الهواتف.`],
  [`one still frame or every frame`, `إطار ثابت واحد أو كل الإطارات`],

  // Audio
  [`Audio`, `الصوت`],
  [`audio`, `الصوت`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `الموسيقى والتسجيلات والمذكرات الصوتية إلى MP3 أو M4A أو WAV أو FLAC أو OGG أو Opus أو AAC أو إلى صيغتي WavPack وTTA دون فقدان. ويمكن قراءة APE وDSD وDTS أيضًا. يستخدم محرك FFmpeg الاختياري.`],
  [`MP3 audio`, `صوت MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 هي صيغة الصوت المضغوط الكلاسيكية. تشغّلها عمليًا كل المشغلات وأنظمة صوت السيارات والهواتف، ما يجعلها الخيار الأضمن لمشاركة الموسيقى والبودكاست والتسجيلات.`],
  [`MPEG-4 audio`, `صوت MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A ملف صوتي بصيغة MPEG-4، عادةً بترميز AAC، يستخدمه iTunes والمذكرات الصوتية في iPhone وكثير من أجهزة التسجيل. جودته جيدة بأحجام صغيرة، لكن بعض المشغلات وأنظمة صوت السيارات لا تقبل إلا MP3.`],
  [`WAV audio`, `صوت WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV صوت غير مضغوط (عادةً PCM) يُستخدم في التسجيل والتحرير. صوته مطابق تمامًا للمصدر، لكنه يشغل نحو 10 ميغابايت لكل دقيقة بجودة CD.`],
  [`FLAC lossless audio`, `صوت FLAC دون فقدان`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC صوت مضغوط دون فقدان: يقلّص حجم الملفات إلى نحو نصف حجم WAV دون أي فقدان في الجودة، ما يجعله الصيغة المفضلة لمكتبات الموسيقى والتنزيلات عالية الدقة.`],

  // Subtitles
  [`Subtitles`, `ملفات الترجمة`],
  [`subtitles`, `ملفات الترجمة`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT وASS وWebVTT وSAMI \u200F(SMI) وLRC وTTML وMicroDVD فيما بينها دون الحاجة إلى أي محرك، مع الحفظ بترميز UTF-8؛ ويمكن قراءة SSA وSCC أيضًا. وتُقرأ ملفات SMI وSRT الكورية بترميز CP949 بصورة صحيحة. أما الترجمة المضمّنة في الفيديو فتُستخرج باستخدام FFmpeg.`],
  [`SubRip subtitles`, `ترجمة SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT \u200F(SubRip) هو ملف الترجمة الأكثر شيوعًا: مقاطع مرقّمة بأوقات بداية ونهاية ونص عادي. وتقبله تقريبًا كل المشغلات وبرامج التحرير ومواقع الفيديو.`],
  [`Advanced SubStation Alpha subtitles`, `ترجمة Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS \u200F(Advanced SubStation Alpha) هي صيغة الترجمة المنسّقة المستخدمة في ترجمات الأنمي التي يعدّها المعجبون وفي Aegisub، مع الخطوط والألوان والمواضع والمؤثرات. ولا تقبل كثير من الأجهزة والمواقع إلا SRT العادية.`],
  [`WebVTT subtitles`, `ترجمة WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT \u200F(\u200E.vtt) هي صيغة الترجمة لفيديو HTML5. وتستخدمها مشغلات الويب وYouTube ومنصات الدورات عبر الإنترنت.`],
  [`SAMI subtitles (SMI)`, `ترجمة SAMI \u200F(SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI \u200F(\u200E.smi) صيغة ترجمة من Microsoft شبيهة بـ HTML. ولا تزال صيغة الترجمة الكلاسيكية في كوريا، وغالبًا ما تُحفظ بترميز CP949 القديم الذي تعرضه المشغلات الحديثة نصًا مشوّهًا.`],

  // Archives
  [`Archives`, `الأرشيفات`],
  [`archives`, `الأرشيفات`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `أعد حزم ZIP و7Z وRAR وTAR وصور الأقراص وكثير غيرها من صيغ الأرشيف أو استخرجها باستخدام محرك 7-Zip المضمّن، أو اجمع أي ملفات في ZIP واحد.`],
  [`ZIP archive`, `أرشيف ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP هي صيغة الأرشيف العالمية. يفتحها Windows وmacOS والهواتف وتقريبًا كل نماذج الرفع دون برامج إضافية.`],
  [`7-Zip archive`, `أرشيف 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z هي صيغة الأرشيف المفتوحة لبرنامج 7-Zip. ويُنتج ضغطها LZMA2 عادةً ملفات أصغر من ZIP، لكن ليس كل نظام أو موقع يستطيع فتحها.`],
  [`RAR archive`, `أرشيف RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR هي صيغة الأرشيف المملوكة لبرنامج WinRAR، وهي شائعة في التنزيلات المقسّمة إلى أجزاء. تستطيع الإصدارات الحديثة من Windows 11 فتح RAR لكنها لا تستطيع إنشاءه، وكثير من الأدوات لا تقبل إلا ZIP.`],
  [`Any files`, `أي ملفات`],

  // CAD drawings
  [`CAD drawings`, `رسومات CAD`],
  [`CAD drawings [in running text]`, `رسومات CAD`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `DWG وDXF من AutoCAD: التحويل بينهما أو إلى PDF وSVG وPNG، دون AutoCAD.`],
  [`AutoCAD drawing`, `رسم AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG هي صيغة الرسم الأصلية في AutoCAD، وأكثر ملفات CAD شيوعًا في العمارة والهندسة. ودون AutoCAD أو عارض DWG يصعب فتحها أو مشاركتها.`],
  [`Drawing Exchange Format`, `صيغة تبادل الرسومات`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF \u200F(Drawing Exchange Format) هي صيغة Autodesk لتبادل رسومات CAD. تقرؤها آلات القص بالليزر وبرامج CNC ومعظم برامج CAD، لذا فهي الطريقة المعتادة لنقل الرسومات بين الأدوات.`],

  // 3D models
  [`3D models`, `النماذج ثلاثية الأبعاد`],
  [`3D models [in running text]`, `النماذج ثلاثية الأبعاد`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB وglTF وSTL وOBJ و3MF وPLY فيما بينها، وFBX إلى أي منها، مع الألوان والخامات والمواد حيثما تحتفظ بها الصيغة، وإلى صورة PNG أو JPG مظلّلة. لا حاجة إلى تثبيت أي شيء.`],
  [`glTF binary (GLB)`, `glTF ثنائي (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB هي نسخة الملف الواحد من glTF، صيغة الأبعاد الثلاثية للويب والواقع المعزز ومحركات الألعاب. وتُجمع فيها الشبكات والمواد والخامات في ملف واحد مدمج.`],
  [`STL 3D model`, `نموذج STL ثلاثي الأبعاد`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL هو الملف الكلاسيكي للطباعة ثلاثية الأبعاد. يخزّن مثلثات الشكل فقط، دون ألوان أو وحدات قياس، وتقرؤه كل برامج التقطيع (slicer) وبرامج CAD.`],
  [`Wavefront OBJ model`, `نموذج Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ \u200F(Wavefront) صيغة ثلاثية الأبعاد بنص عادي تفتحها تقريبًا كل برامج الأبعاد الثلاثية. وتُحفظ المواد والخامات بجانب الملف في ملف \u200E.mtl وملفات صور.`],

  // Fonts
  [`Fonts`, `الخطوط`],
  [`fonts`, `الخطوط`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `خطوط سطح المكتب والويب: TTF وOTF وWOFF وWOFF2 وEOT فيما بينها.`],
  [`TrueType font`, `خط TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF \u200F(TrueType) هي صيغة خطوط سطح المكتب الأكثر شيوعًا على Windows وmacOS. ثبّت الخط لاستخدامه في أي تطبيق.`],
  [`OpenType font`, `خط OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF \u200F(OpenType) صيغة خطوط من Adobe وMicrosoft. وتشيع خطوط OpenType ذات مخططات PostScript \u200F(CFF) في الخطوط الاحترافية، وتدعم ميزات مثل الحروف المركّبة (ligatures).`],
  [`Web font (WOFF2)`, `خط ويب (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 صيغة خطوط الويب المضغوطة التي تدعمها كل المتصفحات الحديثة. وهي عادةً أصغر من WOFF بنحو 30%، فتُحمَّل الصفحات أسرع.`],

  // Geospatial data
  [`Geospatial data`, `البيانات الجغرافية`],
  [`geospatial data`, `البيانات الجغرافية`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `الخرائط وبيانات GPS: GeoJSON وKML وKMZ وGPX وShapefile فيما بينها وإلى CSV وExcel وJSON، وملف CSV فيه إحداثيات إلى ملف خريطة. بيانات متجهية فقط (نقاط وخطوط ومساحات)، تُحفظ دائمًا بخطوط الطول والعرض. لا حاجة إلى تثبيت أي شيء.`],
  [`one row per feature, with its coordinates`,
    `صف لكل عنصر جغرافي مع إحداثياته`],
  [`a CSV with longitude and latitude columns or WKT`,
    `ملف CSV فيه أعمدة لخطوط الطول والعرض أو WKT`],

  // Camera RAW group (conversion pages)
  [`Camera RAW photo`, `صورة RAW من الكاميرا`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `تحتوي ملفات RAW من الكاميرات (CR2 وCR3 وNEF وARW وDNG وRAF وORF وغيرها) على بيانات المستشعر غير المعالجة للصورة. وتحتفظ بأكبر قدر من التفاصيل للتحرير، لكنها كبيرة الحجم وتحتاج إلى برامج خاصة لعرضها.`],

  // Conversion guides: images
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `JPG هو الخيار الآمن عندما يحتاج موقع ويب أو تطبيق Windows قديم أو شخص لا يملك iPhone إلى صورك. وتُحوَّل دفعة كاملة من صور HEIC مرة واحدة، ويُحفظ كل ملف JPG بجانب أصله.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `اختر PNG إذا أردت مواصلة تحرير الصورة دون إضافة جولة أخرى من ضغط JPG. فـ PNG صيغة دون فقدان، لذا توقّع ملفات أكبر بعدة أضعاف من ملف HEIC الأصلي.`],

  // Conversion guides
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `تحفظ صيغة HEIC الصورة في نحو نصف المساحة التي يشغلها JPG بالجودة نفسها، وبها يحفظ iPhone صوره. يتطلب الحفظ بصيغة HEIC محرك FFmpeg المجاني (نحو 100 ميغابايت، يُنزَّل مرة واحدة من داخل التطبيق). وتُحفَظ بيانات EXIF وملف تعريف الألوان واتجاه الصورة.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `كثيرًا ما تكون الصور المحفوظة من مواقع الويب بصيغة WebP. يحافظ التحويل إلى PNG على الجودة كاملة وعلى أي شفافية، فتعمل النتيجة في كل محرر وعرض تقديمي ومستند.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `اختر JPG عندما تكون الصورة فوتوغرافية ويهمّك حجم الملف، مثلًا لنماذج الرفع التي ترفض WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `قد يبلغ حجم لقطات الشاشة والصور المصدَّرة بصيغة PNG عدة ميغابايتات. تصغر الصور الفوتوغرافية عادةً كثيرًا بصيغة JPG، أما لقطات الشاشة المليئة بالنصوص والشعارات فغالبًا ما تبقى PNG الصيغة الأنسب لها.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `لا يعيد تحويل JPG إلى PNG التفاصيلَ التي ضاعت بسبب ضغط JPG، لكنه يوقف المزيد من الفقدان: فكل تعديل وحفظ لاحق يبقى دون فقدان. حوّل الصورة قبل أن تنقّحها أو تضيف إليها شفافية في محرر الصور.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `لا تفتح صور AVIF القادمة من المواقع والهواتف الحديثة في كثير من البرامج القديمة وعارضات الصور ونماذج الرفع. أما JPG فيفتح في كل مكان، مقابل ملفات أكبر قليلًا.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `صيغة WebP مثالية لمواقع الويب: تصغر الصور الفوتوغرافية كثيرًا مقارنةً بـ JPG، وتحتفظ الرسومات بشفافيتها. يحفظ الإعداد المسبق WEBP بجودة 85، وهي موازنة جيدة للويب.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `كثيرًا ما يجب إرسال الصفحات الممسوحة ضوئيًا والإيصالات وصور المستندات في ملف PDF واحد. أفلت الصور على الإعداد المسبق «دمج PDF» لتحصل على ملف PDF واحد، أو على PDF لتحصل على ملف PDF لكل صورة. افتراضيًا تأخذ كل صفحة مقاس صورتها.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `يغطي ملف ICO واحد كل ما يحتاجه Windows من أيقونات لسطح المكتب ومستكشف الملفات وشريط المهام، ويصلح أيضًا أيقونةً لموقع الويب (favicon). ابدأ من صورة PNG مربعة لا تقل عن 256×256 بكسل لتحصل على أوضح نتيجة.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `يتطلب إنشاء أيقونة تطبيق Mac على Windows عادةً أدوات إضافية، أما Filee فيحوّل PNG إلى ملف ICNS مباشرةً. استخدم صورة PNG مربعة بمقاس 1024×1024 بكسل لتبقى مقاسات Retina واضحة.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `شارك تصميم Photoshop مع من لا يملكون Photoshop: يعرض PNG الصورة كما حُفظت، مع دمج الطبقات المرئية والحفاظ على الشفافية. لا يستطيع PNG تخزين الطبقات، لذا احتفظ بملف PSD للتعديل.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `يقرأ Filee ملفات RAW من كاميرات Canon وNikon وSony وFujifilm وOlympus/OM System وPanasonic وPentax وSamsung وLeica وHasselblad وPhase One وغيرها، ويعالجها بالإعدادات الافتراضية. إنها الطريقة السريعة للحصول على صور JPG جاهزة للمشاركة من جلسة تصوير؛ أما للتعديل الإبداعي فاستخدم محرر RAW أولًا.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `أفلت ملفات CR2 من بطاقة ذاكرة كاملة دفعةً واحدة: يحوّلها Filee بالتوازي ويحفظ كل JPG بجوار ملف RAW الخاص به. وتكتب كاميرات Canon الأحدث بصيغة CR3، التي يقرؤها Filee أيضًا.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `ملفات NEF أكبر وأقل شيوعًا من أن تُرسل كما هي. أما بصيغة JPG فتصبح صورًا صغيرة يمكن عرضها في أي مكان؛ استخدم JPG 70% أو الإعداد المسبق «نصف الحجم» لتطبيقات المراسلة. وتعمل ملفات NRW من كاميرات Nikon Coolpix بالطريقة نفسها.`],
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `كثير من التطبيقات والعروض التقديمية ونماذج الرفع لا تقبل SVG. يحوّل Filee الرسم المتجهي إلى PNG مع الحفاظ على الشفافية، ويعمل كذلك مع ملفات SVGZ المضغوطة.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `يبقى التحويل من SVG إلى PDF متجهيًا: تظل الخطوط والنصوص حادة عند أي تكبير وفي الطباعة، ويبقى الملف صغيرًا. مفيد لإرسال الشعارات والمخططات إلى المطبعة أو لإدراجها في المستندات.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `لا يمكن عرض EPS إلا بمفسّر PostScript، ويستخدم Filee لذلك Ghostscript. يحتفظ PDF بالرسم المتجهي، فيفتح في أي مكان ويُطبع بوضوح. وتعمل ملفات PostScript (‎.ps) بالطريقة نفسها.`],
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `تصبح كل صفحة صورة JPG مستقلة، فملف PDF من 10 صفحات يعطيك 10 صور. مفيد للمحادثات والشرائح ومنشورات التواصل الاجتماعي التي تقبل الصور ولا تقبل PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `يحافظ PNG على وضوح النصوص والخطوط دون تشوهات JPG، فيناسب الشرائح والمخططات والنوتات الموسيقية والصفحات التي تريد إضافة ملاحظات عليها أو إدراجها في عرض تقديمي.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `يحوّل Filee ملف PDF إلى مستند Word بفقرات حقيقية بدلًا من صور للصفحات، فتستطيع تصحيح الأخطاء الإملائية أو إعادة استخدام النص. قد تحتاج التخطيطات المعقدة إلى بعض التعديل، أما ملف PDF الممسوح ضوئيًا الذي لا يحتوي إلا صور الصفحات فلا نص فيه لاستخراجه.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `يمرّ Filee تلقائيًا بالمسار PDF → Word → EPUB، فيتكيّف النص مع شاشة الهاتف أو القارئ الإلكتروني. يعمل ذلك على أفضل وجه مع ملفات PDF التي تحتوي نصًا حقيقيًا. تظهر العناوين فقرات عادية، ولا نص في الصفحات الممسوحة ضوئيًا لتحويله.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `ينقل Filee نص ملف PDF إلى مستند Word، ثم يكتبه بصيغة HWPX ويحفظه بعد ذلك بصيغة HWP، وكل ذلك بمحركات مدمجة. يعمل مع ملفات PDF التي تحتوي نصًا حقيقيًا. قد تحتاج التخطيطات المعقدة إلى بعض التعديل، ولا نص في الصفحات الممسوحة ضوئيًا لاستخراجه.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `يحوّل Filee ملف PDF إلى مستند Word أولًا ثم إلى Markdown، محافظًا على الفقرات والعناوين والنص الغامق حيثما استطاع تمييزها. مفيد للملاحظات وصفحات الويكي أو للصق النص في أدوات أخرى. لا نص في الصفحات الممسوحة ضوئيًا لتحويله.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `كثيرًا ما تطلب المكاتب الكورية المستندات بصيغة Hangul. يحوّل Filee نص ملف PDF إلى ملف HWPX يمكنك فتحه وتعديله في Hancom Hangul، دون الحاجة إلى Hancom Office للتحويل؛ ثم حوّله إلى HWP إذا اشترط نموذجٌ ما الصيغة القديمة.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `مفيد عندما يجب عرض ملف PDF في PowerPoint أو إضافته إلى عرض تقديمي قائم: تصبح كل صفحة شريحة تبدو تمامًا مثل PDF، ويُحفظ نص الصفحة في ملاحظات المتحدث. الشرائح صور، لذا حوّل PDF إلى DOCX بدلًا من ذلك إذا أردت تغيير الصياغة.`],
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `لا حاجة إلى Microsoft Word أو LibreOffice: يقرأ Filee ملف DOCX بنفسه وينسّق الصفحات مع الرؤوس والتذييلات والجداول والصور. أفلت عدة مستندات على الإعداد المسبق «دمج PDF» لجمعها في ملف PDF واحد.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `تتحول مستندات Word 97–2003 القديمة من الأرشيفات والنماذج الرسمية والأنظمة القديمة إلى ملفات PDF تفتح في أي مكان. ويحوّل المحرك نفسه أيضًا ملفات ODT وRTF وWPS وWordPerfect وLotus Word Pro وAbiWord وApple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `احفظ رسائل البريد الإلكتروني بصيغة PDF للسجلات أو الفواتير أو الملفات القانونية: يعرض PDF المرسل والمستلمين والتاريخ والموضوع ونص الرسالة، ويفتح في أي مكان دون تطبيق بريد.`],
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `يعرض Filee صفحات HWP باستخدام rhwp، وهو محرك Hangul مفتوح المصدر، فلا دور لـ Hancom Office ولا لمربع حوار الموافقة الخاص به. مفيد لإرسال المستندات الكورية إلى من لا يستطيعون فتح HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `حوّل مستند Hangul إلى ملف Word يستطيع زملاؤك في الخارج تعديله. تُنقل النصوص والفقرات والجداول، ويُستحسن إلقاء نظرة سريعة في Word على التخطيطات التي تكثر فيها العناصر العائمة.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `تُحوَّل HWPX، صيغة Hangul الأحدث القائمة على XML، كما تُحوَّل HWP تمامًا: ينسّق محرك rhwp المدمج الصفحات دون أي اتصال بالإنترنت. مفيد لأرشفة نماذج HWPX الصادرة عن المؤسسات العامة بصيغة PDF.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `بعض الأنظمة وسير العمل الأحدث لا تقبل إلا HWPX. يحوّل Filee ملفات HWP الثنائية إلى HWPX باستخدام rhwp، دون Hancom Office، ويحوّل دفعة كاملة من المستندات القديمة مرة واحدة.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `لا تزال الإصدارات الأقدم من Hangul وبعض بوابات التقديم تطلب ملفات ‎.hwp. يحوّل Filee ملفات HWPX إلى HWP باستخدام rhwp، فلا تضطر إلى فتح كل ملف وإعادة حفظه في Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `ينقل كاتب HWPX الخاص بـ Filee تخطيط Word كما هو: حجم الصفحة والهوامش، والرؤوس والتذييلات مع أرقام الصفحات، والجداول ذات الخلايا المدمجة والحدود والتظليل، ومربعات النص والأشكال والصور. وفي الاختبارات يُفحص كل ملف يكتبه بثلاثة برامج قراءة HWPX مستقلة.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `للمكاتب والنماذج التي لا تزال تطلب ملفات ‎.hwp. يكتب Filee مستند Word بصيغة HWPX بكاتبه الخاص ثم يحوّله إلى HWP باستخدام rhwp، وكلاهما مدمج، فلا حاجة إلى Hancom Office للتحويل.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `تصبح كل صفحة من مستند Word صورة JPG (إذ ينسّق Filee المستند بصيغة PDF أولًا)، وهذا مفيد لنشر صفحة على الإنترنت أو إرسال معاينة سريعة. لا حاجة إلى Word.`],
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `تصبح كل ورقة مرئية قسمًا مستقلًا، مع تنسيقات الأرقام والخطوط والتعبئة والحدود والخلايا المدمجة كما يعرضها Excel. تُصغَّر الأوراق العريضة لتلائم عرض الصفحة مثل خيار Excel «احتواء كافة الأعمدة في صفحة واحدة»، وتتكرر صفوف العناوين المثبّتة في كل صفحة.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `لا يحمل CSV إلا جدولًا واحدًا، لذا يكتب Filee ملف CSV لكل ورقة. وتُصدَّر الخلايا قيمًا جاهزة لقواعد البيانات والسكربتات ونماذج الاستيراد.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `يستطيع مصنف XLSX أن يحمل التنسيق والصيغ والأوراق الإضافية التي لا يستطيع CSV حملها. حدّد كل ملفات CSV المصدَّرة وأفلتها دفعة واحدة لتحصل على مصنف لكل ملف، دون مربع حوار الاستيراد في Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `حدّث مصنفات Excel 97–2003 القديمة دون Excel أو LibreOffice: التحويل مدمج. ملفات XLSX أصغر عادةً، ولا يمكنها حمل وحدات الماكرو، وتفتح في كل تطبيقات جداول البيانات الحالية.`],
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `تصبح كل شريحة صفحة PDF واحدة بمقاس الشريحة، مع النصوص والأشكال والصور والجداول والتصميم الرئيسي. مفيد لتوزيع العروض التقديمية أو رفعها حيث لا تُقبل ملفات PowerPoint. لا يتضمن ملف PDF الحركات ولا ملاحظات المتحدث.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `تتحول عروض PowerPoint 97–2003 القديمة إلى ملفات PDF يستطيع أي شخص فتحها أو طباعتها أو رفعها. وتُحوَّل عروض Keynote (‎.key) وODP وWPS ‏(DPS) بالطريقة نفسها.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `تصبح كل شريحة صورة JPG، جاهزة لمنشورات التواصل الاجتماعي والصور المصغّرة ورسائل الدردشة أو لمحرر الفيديو. اختر PNG بدلًا من ذلك إذا كانت الشرائح مليئة بالنصوص الصغيرة.`],
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `تُنسَّق العناوين والقوائم (بما فيها قوائم المهام) والجداول والشيفرات والاقتباسات والروابط والصور والحواشي والمعادلات الرياضية على صفحات A4، دون Pandoc أو LaTeX أو متصفح. طريقة سريعة لمشاركة الملاحظات وملفات README مع من لا يقرؤون Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `مدمج، دون الحاجة إلى Pandoc. تنتقل العناوين والقوائم والجداول والروابط والحواشي، فتستطيع مواصلة تحرير المستند وتغيير تنسيقه في Word.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `يتحول النص العادي إلى ملف PDF نظيف بمقاس A4 بفقرة لكل سطر. يتعرف Filee على ترميزي UTF-8 وUTF-16 وكذلك على الملفات النصية الكورية القديمة (CP949)، فلا تتحول السجلات والملاحظات القديمة إلى رموز مشوّهة.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `احفظ صفحة ويب أو تقرير HTML بصيغة PDF يبدو كما هو في كل مكان ويمكن أرشفته أو طباعته. يحوّل Filee ملفات ‎.html المحفوظة على حاسوبك، ويمكن دمج عدة ملفات منها في PDF واحد.`],
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `يحافظ PDF على تخطيط ثابت للصفحات، وهذا مفيد لطباعة كتاب إلكتروني أو قراءته على الحاسوب أو إرساله إلى جهاز لا يتوفر فيه قارئ EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `انقل مكتبة Kindle/Mobipocket القديمة إلى EPUB لتفتح في Apple Books وGoogle Play Books وKobo ومعظم تطبيقات القراءة. هذا الاتجاه مدمج، فلا حاجة إلى Calibre.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `تكتب أداة الكتب الإلكترونية Calibre ملفات MOBI وAZW3. وتقبل أجهزة Kindle الحالية أيضًا EPUB عبر Send to Kindle، لذا يفيد MOBI أساسًا لأجهزة Kindle وتطبيقاتها الأقدم.`],
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `احفظ صوت محاضرة أو حفلة موسيقية أو مقابلة بصيغة MP3 تعمل في كل مكان: في السيارة، أو على مشغّل قديم، أو في أداة تفريغ نصي.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `مقاطع الفيديو من iPhone وMac ملفات MOV. وبصيغة MP4 تعمل على هواتف Android وأجهزة التلفاز الذكية وتطبيقات Windows القديمة ونماذج الرفع التي ترفض MOV. وعادةً ما يتوافق الفيديو والصوت مع MP4 كما هما، فيكتفي Filee بنقلهما إلى حاوية جديدة: دون فقدان في الجودة، مع الحفاظ على HDR، وفي ثوانٍ. ويصغّر الإعداد المسبق MP4 720p مقاطع 4K لمشاركتها.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `كثيرًا ما تتعذر إضافة تسجيلات MKV، كتلك التي يسجلها OBS، إلى محررات الفيديو أو تشغيلها على أجهزة التلفاز، بينما يُقبل MP4 في كل مكان تقريبًا. يجري التحويل محليًا، فلا حاجة إلى رفع التسجيلات الطويلة أبدًا.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `كثيرًا ما تكون تسجيلات الشاشة ومقاطع الفيديو المحفوظة من المتصفح بصيغة WebM، التي لا تتعامل معها جيدًا كثير من محررات الفيديو والمشغّلات القديمة وتطبيقات المراسلة. أما MP4 فيعمل في كل مكان تقريبًا، وتُحوَّل دفعة كاملة من المقاطع في آن واحد.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `حوّل مقطعًا قصيرًا إلى صورة GIF متحركة للمحادثات أو التوثيق أو تقارير الأخطاء. واجعله قصيرًا: يخزّن GIF كل إطار صورةً من 256 لونًا، فتنتج مقاطع الفيديو الطويلة أو عالية الدقة ملفات كبيرة جدًا.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `إفلات فيديو على JPG يعطي صورة ثابتة واحدة. لاختيار صورة مصغّرة أو لتصفح مقطع إطارًا بإطار، استخدم الإعداد المسبق «استخراج الإطارات (JPG)»: تُحفظ الصور في مجلد بجوار الفيديو، كل الإطارات أو إطارًا واحدًا من كل N إطارات. ويُرفض قبل البدء أي فيديو قد ينتج أكثر من 100,000 صورة أو يملأ القرص.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `ملفات AVI من كاميرات الفيديو والكاميرات القديمة كبيرة، وكثيرًا ما تستخدم برامج ترميز لم تعد الهواتف وأجهزة التلفاز تشغّلها. أما MP4 بضغط حديث فهو عادةً أصغر بكثير ويعمل في كل مكان.`],
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `يشغل تسجيل WAV نحو 10 ميغابايت لكل دقيقة، أما بصيغة MP3 فيحتاج إلى جزء صغير من ذلك ويبقى قابلًا للتشغيل على كل جهاز.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `احتفظ بمكتبة FLAC عديمة الفقدان في المنزل، وضع نسخًا بصيغة MP3 على الهاتف أو على ذاكرة USB للسيارة أو على مشغّل قديم لا يشغّل FLAC. وتُحوَّل الألبومات كاملة دفعة واحدة.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `تنتج المذكرات الصوتية في iPhone وتنزيلات iTunes الخالية من DRM وكثير من أجهزة التسجيل ملفات M4A. أما MP3 فيقبله كل مشغّل ونظام صوت في السيارة ونموذج رفع.`],
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `أعد حزم أرشيفات RAR بصيغة ZIP للأشخاص ونماذج الرفع والأنظمة التي لا تقبل إلا ZIP. لا حاجة إلى WinRAR، لا لقراءة RAR ولا لكتابة ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `غالبًا ما يضغط 7Z بشكل أفضل، لكن ZIP يفتح على أي حاسوب أو هاتف دون برامج إضافية. حوّل الأرشيف عندما ترسله إلى شخص لا يملك 7-Zip.`],
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `أرسل الرسومات إلى العملاء أو فرق المواقع أو المطابع التي لا تملك AutoCAD: يفتح PDF على أي حاسوب أو هاتف. ويمكن دمج عدة رسومات في PDF واحد.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `تتحول ملفات DXF الصادرة عن برامج CAD أو مهام القص بالليزر أو تبادل التصاميم إلى ملفات PDF يستطيع أي شخص فتحها وطباعتها. ويتوفر أيضًا SVG وPNG، مثلًا للمعاينة على الويب.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF هي صيغة التبادل التي تقرؤها آلات القص بالليزر وبرامج CNC ومعظم برامج CAD. يتيح لك تحويل DWG إلى DXF فتح رسومات AutoCAD في تلك الأدوات، كما يعمل التحويل العكسي من DXF إلى DWG.`],
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `استضف الخط على موقعك بنفسك: WOFF2 هي صيغة خطوط الويب المضغوطة التي تدعمها كل المتصفحات الحديثة، وهي عادةً أصغر من WOFF بنحو 30%. تأكد من أن ترخيص الخط يسمح بتضمينه في مواقع الويب.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `بعض البرامج القديمة وآلات القص والتطريز ومحركات الألعاب لا تقبل إلا خطوط TrueType. حوّل عائلة خطوط OTF كاملة إلى TTF دفعة واحدة، دون محرر خطوط.`],
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `استخدم «رسم خطي إلى SVG» للشعارات والتواقيع والمستندات الممسوحة ضوئيًا: يصبح الحبر شكلًا أسود واحدًا على خلفية شفافة. أما «تتبّع إلى SVG» فيحتفظ بما يصل إلى 64 لونًا للأيقونات والرسوم التوضيحية. تخرج الصور الفوتوغرافية على هيئة بقع لونية مسطحة، لذا يناسب التتبّع الرسومات أكثر.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `تتحول صورة JPG لشعار أو لرسم تخطيطي ممسوح ضوئيًا إلى SVG يبقى حادًا بأي حجم، جاهزًا لراسمة القص أو لموقع ويب أو للمطبعة. يتحول تشويش JPG إلى نقاط صغيرة، لذا خفّض قيمة «التفاصيل» في الإعداد المسبق إذا بدت النتيجة مزدحمة.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `تقرأ آلات القص بالليزر وبرامج CNC وبرامج CAD صيغة DXF. يكتب Filee حدود أشكال SVG بالمليمتر، فالشكل الذي عرضه 100 مم يبقى 100 مم. وتصبح المنحنيات خطوطًا متعددة دقيقة، وتُستبعد التعبئات والصور والمرشّحات.`],
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `رسائل البريد التي تسحبها من Outlook هي ملفات MSG لا يفتحها إلا Outlook. أما بصيغة PDF فتحتفظ بالمرسل والمستلمين والتاريخ والموضوع ونص الرسالة، وتفتح في أي مكان. لا حاجة إلى Outlook.`],
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML أسهل في القراءة والتعديل يدويًا، ولهذا تعتمده ملفات الإعدادات. تحتفظ المفاتيح بترتيبها، ويوضع بين علامتي اقتباس أي نص قد يُقرأ لاحقًا رقمًا أو true/false.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `حوّل ملف إعدادات إلى JSON لواجهة برمجة أو سكربت أو أداة لا تقرأ إلا JSON. تُستبدل المراسي والأسماء المستعارة (anchors وaliases) بقيمها، ويصبح الملف الذي يضم عدة مستندات مصفوفة واحدة. وتُحذف التعليقات، إذ لا يدعمها JSON.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `تتحول قائمة سجلات JSON إلى جدول يمكنك فتحه في Excel: صف لكل سجل وعمود لكل مفتاح. ويُتجاوز الغلاف مثل {"users": […]} للوصول إلى ما بداخله. أما البيانات التي ليست جدولًا فيتوقف تحويلها برسالة توضيحية بدلًا من ملف تالف.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `انقل دفتر العناوين إلى Excel أو إلى أداة مراسلات بريدية: صف لكل جهة اتصال يضم الاسم والمؤسسة والبريد الإلكتروني والهاتف والعنوان وتاريخ الميلاد. وتُقرأ جهات الاتصال من الهواتف الكورية القديمة بترميز CP949 بشكل صحيح.`],
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `تتطلب مشغّلات الويب ومنصات الدورات الإلكترونية صيغة WebVTT. تنتقل التوقيتات وفواصل الأسطر والخط المائل، ولا حاجة إلى أي محرك.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `كثير من المشغّلات وأجهزة التلفاز والمحررات لا تقرأ SMI، وكثيرًا ما تظهر ملفات SMI الكورية القديمة نصًا مشوّهًا. يكتشف Filee ترميز CP949، ويختار اللغة صاحبة أكبر عدد من الأسطر، ويحفظ ملف SRT نظيفًا بترميز UTF-8.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `عندما يرفض تلفاز أو هاتف أو موقع فيديو ترجمات ASS المنسّقة، فإن SRT البسيط يفي بالغرض. يُحتفظ بالغامق والمائل والتسطير والألوان، وتُحذف المواضع والخطوط والتأثيرات.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `استخرج الترجمة المضمّنة في فيلم لتعديلها أو نقلها إلى لغة أخرى. يُحفظ أول مسار ترجمة نصي بصيغة SRT، أما الترجمات القائمة على الصور (DVD وBlu-ray) فلا يمكن تحويلها إلى نص. يتطلب محرك FFmpeg المجاني.`],
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `افتح ملف طباعة ثلاثية الأبعاد في برنامج 3D يفضّل OBJ. لا يحمل STL وحدات قياس، لذا يقرؤه Filee بالمليمتر ويكتب OBJ بالمليمتر أيضًا، مع توجيه المحور Y إلى الأعلى كما في معظم برامج 3D.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `تقبل برامج التقطيع (slicers) الخاصة بالطابعات ثلاثية الأبعاد صيغة STL. تُقسَّم الأوجه أيًّا كان شكلها إلى مثلثات، ويتحول المحور العلوي من Y إلى Z، فيقف النموذج المنتصب على سطح الطباعة كما ينبغي. لا يحتفظ STL إلا بالشكل، لذا تبقى الألوان والخامات في ملف OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `انقل نموذجًا من الويب أو من محرك ألعاب إلى برنامج يقرأ OBJ. يُكتب ملف ‎.mtl والخامات بجوار ملف ‎.obj، فاحتفظ بها معًا.`],

  // FAQ
  [`Is Filee really free?`,
    `هل Filee مجاني حقًا؟`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `نعم. Filee مجاني ومفتوح المصدر بموجب ترخيص MIT: بلا إعلانات ولا علامات مائية ولا حساب ولا فترة تجريبية، ولا يفرض من جهته أي حد على عدد الملفات أو حجمها.`],
  [`Does it work offline? Are my files uploaded?`,
    `هل يعمل دون اتصال بالإنترنت؟ هل تُرفع ملفاتي؟`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `تجري كل عملية تحويل على حاسوبك، ولا تُرفع الملفات أبدًا. لا يُستخدم الإنترنت إلا لتنزيل محرك اختياري أو للتحقق من التحديثات، فتبقى المستندات السرية والصور والتسجيلات على جهازك.`],
  [`Which file formats does Filee support?`,
    `ما صيغ الملفات التي يدعمها Filee؟`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `يقرأ Filee {formatTotal} صيغة ملفات موزعة على {categoryCount} فئة: {categoryList}. يعمل {builtinTotal} منها فور التثبيت، وتستخدم البقية محركًا اختياريًا مجانيًا. ويسرد دليل الصيغ كل صيغة وما يمكن تحويلها إليه.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `هل أحتاج إلى Microsoft Office أو Hancom Office أو LibreOffice؟`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF.`,
    `لا. تُحوَّل ملفات Word وExcel وPowerPoint (DOCX وXLSX وXLS وCSV وPPTX) ومستندات HWP/HWPX الكورية بمحركات مدمجة في Filee. ولا يستخدم Filee برامج Office أو Hancom Office حتى إن كانت مثبّتة؛ أما LibreOffice فهو مجرد تنزيل اختياري من داخل التطبيق للصيغ الأقدم مثل DOC وPPT وODT وRTF.`],
  [`What are the optional engines?`,
    `ما المحركات الاختيارية؟`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `المحركات الكبيرة غير مضمّنة في برنامج التثبيت. حدّدها في صفحة المحركات ضمن برنامج التثبيت، أو نزّلها من داخل Filee متى احتجت إليها: {engineDetails}. تُحفظ في مجلد Filee الخاص ويمكن إزالتها في أي وقت، ويعرض التطبيق إصداراتها وسرعة التنزيل والوقت المتبقي. وإذا كان FFmpeg أو calibre أو Pandoc أو Ghostscript أو LibreOffice موجودًا على حاسوبك بالفعل (في PATH، بما في ذلك Scoop، أو في Program Files)، يستخدمه Filee ويتخطى التنزيل، وينبّهك إن كانت تلك النسخة أقدم من الإصدار الذي اختُبر عليه. ويتيح الخيار «استخدام نسختي…» في الإعدادات ← المحركات اختيار نسخة بعينها.`],
  [`Does installing Filee need administrator rights?`,
    `هل يحتاج تثبيت Filee إلى صلاحيات المسؤول؟`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `مرة واحدة فقط، أثناء التثبيت. يضع برنامج التثبيت Filee في Program Files لجميع المستخدمين، ويضيف في Windows 11 الخيار «تحويل باستخدام Filee» إلى أعلى قائمة مستكشف الملفات. بعد ذلك يعمل Filee نفسه بصلاحيات المستخدم العادي. للتثبيت الصامت، شغّل برنامج التثبيت مع ‎/VERYSILENT /SUPPRESSMSGBOXES. وإن لم تكن تستطيع تثبيت البرامج، فاستخدم ملف ZIP المحمول: فك ضغطه في أي مكان وشغّل Filee.exe.`],
  [`Can I convert many files at once?`,
    `هل يمكنني تحويل ملفات كثيرة دفعة واحدة؟`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `نعم. حدّد ما تشاء من الملفات وأفلتها مرة واحدة: يحوّلها Filee بالتوازي، ولا يوقف فشلُ ملف واحد بقيةَ الملفات، ويمكن للإعدادات المسبقة دمج كل شيء في PDF واحد أو ضغطه في ملف ZIP واحد.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `هل يمكنني التحويل من قائمة النقر بزر الماوس الأيمن في Windows 11؟`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `نعم. انقر بزر الماوس الأيمن على الملفات في مستكشف الملفات واختر «تحويل باستخدام Filee». وفي Windows 11 يمكنك أيضًا وضع الخيار في القائمة الرئيسية دون المرور بـ«إظهار المزيد من الخيارات»: انقر «إضافة إلى القائمة الرئيسية» في الإعدادات ← عام مرة واحدة ووافق على طلب صلاحيات المسؤول. وتعمل أيضًا قائمة «إرسال إلى» واختصار لوحة المفاتيح ومنطقة الإفلات في النافذة الرئيسية.`],
  [`Can Filee convert from the command line or automatically?`,
    `هل يستطيع Filee التحويل من سطر الأوامر أو تلقائيًا؟`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `نعم. يمكن لبرنامج التثبيت إضافة الأمر filee إلى PATH: يحوّل الأمر filee convert *.heic --to jpg الملفات وأنماط أحرف البدل والمجلدات باستخدام إعداداتك المسبقة، ويطبع JSON للسكربتات ويعيد رموز الخروج. وتحوّل مجلدات المراقبة تلقائيًا الملفات التي تصل إلى مجلد ما، ويمكنها نقل الملفات الأصلية جانبًا. اضبطها من صفحة «مراقبة المجلدات» في التطبيق أو بالأمر filee watch في الطرفية.`],
  [`How do I convert a file, for example HEIC to JPG?`,
    `كيف أحوّل ملفًا، مثلًا من HEIC إلى JPG؟`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `حدّد الملفات في مستكشف الملفات، واضغط باستمرار على Ctrl (أو المفتاح الذي اخترته) واسحبها. يظهر عند المؤشر شريط دائري من الصيغ: أفلت الملفات على JPG فتظهر الملفات الجديدة بجوار الأصلية. وتتوفر أدلة خطوة بخطوة لأكثر التحويلات شيوعًا.`],
  [`Why use Filee instead of an online converter?`,
    `لماذا أستخدم Filee بدلًا من محوّل عبر الإنترنت؟`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `ترفع المحوّلات عبر الإنترنت ملفاتك إلى خادم شخص آخر، وغالبًا ما تقيّد حجم الملفات وعددها، وتعتمد على اتصال سريع. أما Filee فيحوّل على حاسوبك: تبقى ملفاتك الخاصة خاصة، ولا مشكلة مع مقاطع الفيديو الكبيرة ولا مع مئات الملفات، ويعمل دون إنترنت، مجانًا وبلا إعلانات.`],
  [`Which operating systems are supported?`,
    `ما أنظمة التشغيل المدعومة؟`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `يتوفر Filee بإصدارات كاملة لنظامي Windows 10 و11 (64 بت) وLinux (x64 وARM64، Ubuntu 22.04 أو أحدث). على Linux تحتاج إيماءة السحب إلى جلسة X11، وهي تجريبية على KDE Plasma مع Wayland، أما على أسطح مكتب Wayland الأخرى فتعمل منطقة الإفلات وقائمة النقر بالزر الأيمن في مدير الملفات. أما macOS 13 أو أحدث (Apple silicon وIntel) فإصدار معاينة: لم يحصل التطبيق بعد على توثيق Apple (notarization)، لذا يطلب منك macOS السماح له مرة واحدة ضمن «الخصوصية والأمن». اختر نظامك في قسم التنزيل.`],
]);
